// header switcher. Guide pairs (NL slug -> EN slug) are added when both guide files exist. No automatic redirects.
const PAIRS = [['/', '/en/'], ['/stroomprijs-vandaag/', '/en/electricity-price-today/'], ['/stroomprijs-morgen/', '/en/electricity-price-tomorrow/'], ['/gasprijs-vandaag/', '/en/gas-price-today/'], ['/dynamisch-vs-vast-contract/', '/en/dynamic-vs-fixed-contract/'], ['/veelgestelde-vragen/', '/en/faq/'], ['/zo-rekenen-we/', '/en/methodology/'], ['/privacy/', '/en/privacy/'], ['/gidsen/', '/en/guides/'], ['/over/', '/en/about/']];
const GUIDE_PAIRS = { 'dynamische-stroomprijs-hoe-werkt-het': 'dynamic-electricity-price-how-it-works', 'goedkoopste-uren-stroom-vandaag': 'cheapest-electricity-hours-today' };
const ALT = {}; // path -> { nl, en }
const pair = (nl, en) => { ALT[nl] = ALT[en] = { nl, en }; };
for (const [nl, en] of PAIRS) pair(nl, en);
const LOGO = logo();
const GOATCOUNTER = '<script data-goatcounter="https://stroomprijs.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script>';
// Before first paint: stored theme (no flash) and the "js" class that reveals the interactive controls.
const HEAD_JS = `<script>(function(d){try{var t=localStorage.getItem('sp-theme');if(t==='light'||t==='dark')d.dataset.theme=t}catch(e){}d.classList.add('js')})(document.documentElement)</script>`;
const THEME_JS = `(()=>{const b=document.getElementById('theme');if(!b)return;const h=document.documentElement,en=h.lang==='en',T=['auto','light','dark'],L=en?{auto:'Auto',light:'Light',dark:'Dark'}:{auto:'Automatisch',light:'Licht',dark:'Donker'};
const set=t=>{if(t==='auto')delete h.dataset.theme;else h.dataset.theme=t;b.dataset.t=t;b.querySelector('.tt-l').textContent=L[t];b.setAttribute('aria-label',en?'Colour scheme: '+L[t].toLowerCase()+'. Click to change.':'Kleurenschema: '+L[t].toLowerCase()+'. Klik om te wisselen.')};
let t='auto';try{t=localStorage.getItem('sp-theme')||'auto'}catch(e){}set(T.includes(t)?t:'auto');
b.addEventListener('click',()=>{const n=T[(T.indexOf(b.dataset.t)+1)%3];try{localStorage.setItem('sp-theme',n)}catch(e){}set(n)})})();`.replace(/\n/g, '');
const APP_JS = `(()=>{const R=(${makeRender.toString()})(document.documentElement.lang==='en'?'en':'nl');\n${fs.readFileSync('lib/app.js', 'utf8')}\n})();`;
const THEME_BTN = (en = false) => `<button class="tt js-only" id="theme" type="button" data-t="auto" aria-label="${en ? 'Colour scheme: auto. Click to change.' : 'Kleurenschema: automatisch. Klik om te wisselen.'}"><svg class="i-a" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8"/><path d="M12 4a8 8 0 0 1 0 16z" fill="currentColor"/></svg><svg class="i-l" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.3 5.3l1.4 1.4M17.3 17.3l1.4 1.4M5.3 18.7l1.4-1.4M17.3 6.7l1.4-1.4"/></svg><svg class="i-d" viewBox="0 0 24 24" aria-hidden="true"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg><span class="tt-l">${en ? 'Auto' : 'Automatisch'}</span></button>`;
const jsonLd = o => JSON.stringify(o).replace(/</g, '\\u003c'); // no "</script>" from content inside the JSON-LD block
const ORG = { '@type': 'Organization', '@id': SITE + '/#org', name: 'CerberosTech', url: 'https://github.com/CerberosTech' };
const crumbs = (...items) => ({ '@type': 'BreadcrumbList', itemListElement: [['Stroomprijs', items[0]?.[1].startsWith('/en/') ? '/en/' : '/'], ...items].map(([name, p], i) => ({ '@type': 'ListItem', position: i + 1, name, item: SITE + p })) });
const graph = (...nodes) => ({ '@context': 'https://schema.org', '@graph': nodes });

// modified: the date (or date-time) the page last changed. It becomes the sitemap <lastmod> and dateModified in the
// JSON-LD: on the Article, FAQPage or AboutPage node if there is one, else on a WebPage node added for it.
const LASTMOD = {};
function page(p, { title, desc, body, schema, type = 'website', modified, app = false }) {
  const url = SITE + p, en = p.startsWith('/en/'), home = en ? '/en/' : '/', alt = ALT[p];
  if (modified) {
    LASTMOD[p] = modified; schema = schema || graph();
    const n = schema['@graph'].find(x => ['Article', 'FAQPage', 'AboutPage'].includes(x['@type']));
    if (n) n.dateModified = n.dateModified || modified; else schema['@graph'].push({ '@type': 'WebPage', '@id': url + '#page', url, name: title, inLanguage: en ? 'en' : 'nl-NL', isPartOf: { '@id': SITE + (en ? '/en/' : '/') + '#site' }, dateModified: modified });
  }
  const nav = NAV[en ? 'en' : 'nl'].map(([h, t]) => `<a href="${BASE}${h}"${h === p || (h !== home && p.startsWith(h)) ? ' aria-current="page"' : ''}>${t}</a>`).join('');
  // Language switcher: the same page in the other language (or that language's home page). A plain link, so it works without JavaScript.
  const sw = en ? `<a class="lang" href="${BASE}${alt ? alt.nl : '/'}" hreflang="nl" lang="nl" aria-label="Deze pagina in het Nederlands">NL</a>` : `<a class="lang" href="${BASE}${alt ? alt.en : '/en/'}" hreflang="en" lang="en" aria-label="This page in English">EN</a>`;
  const hreflang = alt ? `<link rel="alternate" hreflang="nl" href="${SITE}${alt.nl}"><link rel="alternate" hreflang="en" href="${SITE}${alt.en}"><link rel="alternate" hreflang="x-default" href="${SITE}${alt.nl}">` : '';
  if (en) return write(p, `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${url}">${hreflang}<meta name="color-scheme" content="light dark"><meta name="theme-color" content="#f2f4f3" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#0b1520" media="(prefers-color-scheme: dark)">${HEAD_JS}<link rel="icon" href="${BASE}/icon.svg" type="image/svg+xml"><link rel="icon" href="${BASE}/favicon.png" sizes="64x64" type="image/png"><link rel="apple-touch-icon" href="${BASE}/apple-touch-icon.png"><link rel="manifest" href="${BASE}/site.webmanifest"><meta property="og:type" content="${type}">${modified && type === 'article' ? `<meta property="article:modified_time" content="${modified}">` : ''}<meta property="og:locale" content="en_GB">${alt ? '<meta property="og:locale:alternate" content="nl_NL">' : ''}<meta property="og:site_name" content="Stroomprijs"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${SITE}/og.png"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Stroomprijs: dynamic electricity prices per hour in the Netherlands, today and tomorrow, with the cheapest hours"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(desc)}"><meta name="twitter:image" content="${SITE}/og.png"><link rel="alternate" type="application/rss+xml" title="Cheapest hours tomorrow (feed in Dutch)" href="${SITE}/feed.xml">${schema ? `<script type="application/ld+json">${jsonLd(schema)}</script>` : ''}${GOATCOUNTER}<style>${CSS}</style></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="in"><a class="brand" href="${BASE}/en/" aria-label="Stroomprijs, to the dashboard">${LOGO}</a><nav aria-label="Main menu">${nav}</nav>${sw}${THEME_BTN(true)}</div></header><main id="main" class="in">${body}</main><footer class="foot"><div class="in">${LOGO}<p>Source: day-ahead prices (EPEX Spot, published via the <a href="https://transparency.entsoe.eu/">ENTSO-E</a> Transparency Platform), fetched through the public <a href="https://www.energyzero.nl/">EnergyZero</a> API. Last updated: ${esc(fetchedEn)}. Refreshed every hour. All times are Dutch local time (CET/CEST). Not advice; check your own supplier’s rates.</p><p><a href="${BASE}/en/about/">About</a> · <a href="${BASE}/en/methodology/">How we calculate</a> · <a href="${BASE}/en/privacy/">Privacy &amp; disclosure</a> · <a href="${BASE}/feed.xml">RSS (Dutch)</a> · <a href="${BASE}/goedkoopste-uren.ics">Calendar (.ics)</a> · <a href="${BASE}/prices.json">Data (JSON)</a> · <a href="https://github.com/CerberosTech/stroomprijs">Source code</a></p><p>More free tools: <a href="https://cerberostech.github.io/isde-checker/" hreflang="nl">ISDE subsidy checker for heat pumps (in Dutch)</a> · <a href="https://cerberostech.github.io/deadorsupported/">Dead or Supported</a> · <a href="https://cerberostech.github.io/belastingcalculator/" hreflang="nl">Dutch income tax calculator 2026 (in Dutch)</a></p></div></footer>${app ? dataTag : ''}<script>${THEME_JS}</script>${app ? `<script>${APP_JS}</script>` : ''}</body></html>`);
  const html = `<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${url}">${hreflang}<meta name="color-scheme" content="light dark"><meta name="theme-color" content="#f2f4f3" media="(prefers-color-scheme: light)"><meta name="theme-color" content="#0b1520" media="(prefers-color-scheme: dark)">${HEAD_JS}<link rel="icon" href="${BASE}/icon.svg" type="image/svg+xml"><link rel="icon" href="${BASE}/favicon.png" sizes="64x64" type="image/png"><link rel="apple-touch-icon" href="${BASE}/apple-touch-icon.png"><link rel="manifest" href="${BASE}/site.webmanifest"><meta property="og:type" content="${type}">${modified && type === 'article' ? `<meta property="article:modified_time" content="${modified}">` : ''}<meta property="og:locale" content="nl_NL">${alt ? '<meta property="og:locale:alternate" content="en_GB">' : ''}<meta property="og:site_name" content="Stroomprijs"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${url}"><meta property="og:image" content="${SITE}/og.png"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Stroomprijs: dynamische stroomprijs per uur, vandaag en morgen, met de goedkoopste uren"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(desc)}"><meta name="twitter:image" content="${SITE}/og.png"><link rel="alternate" type="application/rss+xml" title="Goedkoopste uren morgen" href="${SITE}/feed.xml">${schema ? `<script type="application/ld+json">${jsonLd(schema)}</script>` : ''}${GOATCOUNTER}<style>${CSS}</style></head><body><a class="skip" href="#main">Naar de inhoud</a><header class="top"><div class="in"><a class="brand" href="${BASE}/" aria-label="Stroomprijs, naar het dashboard">${LOGO}</a><nav aria-label="Hoofdmenu">${nav}</nav>${sw}${THEME_BTN()}</div></header><main id="main" class="in">${body}</main><footer class="foot"><div class="in">${LOGO}<p>Bron: day-ahead prijzen (EPEX Spot, gepubliceerd via <a href="https://transparency.entsoe.eu/">ENTSO-E</a>) opgehaald via de publieke <a href="https://www.energyzero.nl/">EnergyZero</a>-API. Laatst bijgewerkt: ${esc(fetchedNl)}. Wordt elk uur ververst. Geen advies; controleer de tarieven van je eigen leverancier.</p><p><a href="${BASE}/over/">Over Stroomprijs</a> · <a href="${BASE}/zo-rekenen-we/">Zo rekenen we</a> · <a href="${BASE}/privacy/">Privacy &amp; disclosure</a> · <a href="${BASE}/feed.xml">RSS</a> · <a href="${BASE}/goedkoopste-uren.ics">Agenda (.ics)</a> · <a href="${BASE}/prices.json">Data (JSON)</a> · <a href="https://github.com/CerberosTech/stroomprijs">Broncode</a></p><p>Meer gratis tools: <a href="https://cerberostech.github.io/isde-checker/">ISDE-subsidiechecker warmtepompen</a> · <a href="https://cerberostech.github.io/deadorsupported/">Dead or Supported</a> · <a href="https://cerberostech.github.io/belastingcalculator/">Belastingcalculator 2026</a></p></div></footer>${app ? dataTag : ''}<script>${THEME_JS}</script>${app ? `<script>${APP_JS}</script>` : ''}</body></html>`;
  write(p, html);
}
// GoatCounter click events on every bol.com partner link (bol-<name>), .ics link (ics-download), RSS feed link
// (rss-feed), JSON data link (data-json) and link to another CerberosTech tool (tool-<name> in the page, footer-<name> in
// the footer), in both languages and inside guide text too. Links that already have an event keep it: the planner's .ics
// button (plan-ics), the vergelijker disclosure link and the 404 buttons are tagged where they are written.
const TOOL = /^https:\/\/cerberostech\.github\.io\/(isde-checker|deadorsupported|belastingcalculator)\//;
const clickEvent = (href, foot) => /^https:\/\/partner\.bol\.com\//.test(href) ? 'bol-' + (/[?&](?:amp;)?name=([\w-]+)/.exec(href)?.[1] || 'link') : /\.ics(?:[?#]|$)/.test(href) ? 'ics-download' : /\/feed\.xml(?:[?#]|$)/.test(href) ? 'rss-feed' : /\/prices\.json(?:[?#]|$)/.test(href) ? 'data-json' : TOOL.test(href) ? (foot ? 'footer-' : 'tool-') + TOOL.exec(href)[1] : '';
const tag = (html, foot) => html.replace(/<a ([^>]*?)href="([^"]*)"/g, (m, pre, href) => { const ev = !pre.includes('data-goatcounter-click') && clickEvent(href, foot); return ev ? `<a ${pre}href="${href}" data-goatcounter-click="${ev}"` : m; });
const track = html => { const i = html.indexOf('<footer'); return i < 0 ? tag(html, false) : tag(html.slice(0, i), false) + tag(html.slice(i), true); };
function write(p, html) { const f = path.join(OUT, p, p.endsWith('/') ? 'index.html' : ''); fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, track(html)); }

fs.rmSync(OUT, { recursive: true, force: true }); fs.mkdirSync(OUT, { recursive: true });
for (const f of fs.readdirSync('static')) fs.copyFileSync(path.join('static', f), path.join(OUT, f));
const assets = writeAssets(fs, path, OUT); // logo mark, favicons, og.png/og.svg: rendered from code, no binary files in the repo
fs.writeFileSync(path.join(OUT, 'site.webmanifest'), JSON.stringify({ name: 'Stroomprijs', short_name: 'Stroomprijs', description: 'Dynamische stroomprijs per uur, vandaag en morgen.', lang: 'nl', start_url: `${BASE}/`, scope: `${BASE}/`, display: 'standalone', background_color: '#f2f4f3', theme_color: '#0f2230', icons: [{ src: `${BASE}/icon-192.png`, sizes: '192x192', type: 'image/png', purpose: 'any maskable' }, { src: `${BASE}/icon-512.png`, sizes: '512x512', type: 'image/png', purpose: 'any maskable' }, { src: `${BASE}/icon.svg`, sizes: 'any', type: 'image/svg+xml' }] }));
console.log('brand assets:', assets.join(', '));

// ---------- dashboard ----------
const btns = `<div class="btns"><a class="btn" href="${BASE}/goedkoopste-uren.ics">${ico('cal')}Goedkoopste uren in je agenda</a><a class="btn alt" href="${BASE}/feed.xml">${ico('rss')}RSS-feed</a></div>`;
const gasCard = `<section class="sec" aria-labelledby="gas-h"><h2 id="gas-h">Gasprijs nu</h2><div data-c="gas">${R.gas(C)}</div><p class="note"><a href="${BASE}/gasprijs-vandaag/">Meer over de gasprijs</a></p></section>`;
const dataset = { '@type': 'Dataset', name: 'Dynamische stroom- en gasprijzen Nederland, vandaag en morgen', description: 'Day-ahead uurprijzen voor stroom (EUR per kWh) en dagprijzen voor gas (EUR per m³) in Nederland, excl. btw, voor vandaag en morgen. Bron: EPEX Spot day-ahead via de publieke EnergyZero-API. Elk uur ververst.', url: SITE + '/', inLanguage: 'nl-NL', isAccessibleForFree: true, creator: { '@id': ORG['@id'] }, isBasedOn: 'https://www.energyzero.nl/', temporalCoverage: `${TODAY}/${TOMORROW}`, spatialCoverage: { '@type': 'Place', name: 'Nederland' }, dateModified: LIVE_UPDATED, distribution: [{ '@type': 'DataDownload', encodingFormat: 'application/json', contentUrl: SITE + '/prices.json' }] };
// Dataset for one day of hourly power prices (the today and tomorrow pages, both languages).
const dayDataset = (p, d, en = false) => ({ ...dataset, '@id': SITE + p + '#dataset', url: SITE + p, temporalCoverage: d, ...(en
  ? { name: `Hourly day-ahead electricity prices in the Netherlands, ${d === TODAY ? 'today' : 'tomorrow'}`, description: `Day-ahead hourly electricity prices in the Netherlands for ${RE.nlDate(d)} (EUR per kWh, excl. VAT, times in CET/CEST). Source: EPEX Spot day-ahead via the public EnergyZero API. Refreshed every hour.`, inLanguage: 'en', spatialCoverage: { '@type': 'Place', name: 'Netherlands' } }
  : { name: `Dynamische stroomprijs per uur in Nederland, ${d === TODAY ? 'vandaag' : 'morgen'}`, description: `Day-ahead uurprijzen voor stroom in Nederland voor ${nlDate(d)} (EUR per kWh, excl. btw). Bron: EPEX Spot day-ahead via de publieke EnergyZero-API. Elk uur ververst.` }) });
page('/', { app: true, modified: LIVE_UPDATED, title: 'Stroomprijs nu, vandaag en morgen – prijs per uur', desc: 'De dynamische stroomprijs van nu, per uur voor vandaag en morgen. Met prijsklasse A–G, de goedkoopste uren voor je wasmachine of auto, een kostenberekening en een schatting incl. belasting.', schema: graph({ '@type': 'WebSite', '@id': SITE + '/#site', name: 'Stroomprijs', url: SITE + '/', inLanguage: 'nl-NL', publisher: { '@id': ORG['@id'] } }, ORG, dataset), body: `${stale}${modebar()}
<section class="hero" data-c="hero" aria-labelledby="nu">${R.hero(C)}</section>${btns}
${planner('nu')}
${daySec('sel', 'Prijs per uur')}
<p class="no-js note">De prijzen van morgen staan op <a href="${BASE}/stroomprijs-morgen/">Stroomprijs morgen</a>.</p>
<div class="duo">${gasCard}<section class="sec"><h2>Meer weten?</h2><ul class="links"><li><a href="${BASE}/zo-rekenen-we/">Zo schatten we de prijs incl. belasting</a></li><li><a href="${BASE}/dynamisch-vs-vast-contract/">Dynamisch vs vast contract</a></li><li><a href="${BASE}/gidsen/">Gidsen over dynamische prijzen</a></li><li><a href="${BASE}/veelgestelde-vragen/">Veelgestelde vragen</a></li><li><a href="https://cerberostech.github.io/isde-checker/">Subsidie op je warmtepomp checken (ISDE)</a></li></ul></section></div>
${placeholder}${meet}${updated}` });

// ---------- vandaag / morgen ----------
page('/stroomprijs-vandaag/', { app: true, title: `Stroomprijs vandaag (${nlDate(TODAY)}) – prijs per uur`, desc: 'De dynamische stroomprijs van vandaag per uur, met prijsklasse A–G, het goedkoopste en duurste uur, het goedkoopste blok en een schatting incl. belasting.', modified: LIVE_UPDATED, schema: graph(crumbs(['Stroomprijs vandaag', '/stroomprijs-vandaag/']), dayDataset('/stroomprijs-vandaag/', TODAY)), body: `<header class="pg-h"><h1>Stroomprijs vandaag</h1><p>${nlDate(TODAY)}</p></header>${stale}${modebar()}${daySec('today', 'Prijs per uur')}${planner('today')}<div class="prose"><p>De prijzen komen uit de day-ahead veiling van EPEX Spot voor het Nederlandse biedgebied. Die veiling vindt de dag ervoor rond 12:00 uur plaats; de uitslag wordt ook gepubliceerd op het ENTSO-E Transparency Platform. Bekijk ook de <a href="${BASE}/stroomprijs-morgen/">stroomprijs van morgen</a>.</p></div>${placeholder}${updated}` });
page('/stroomprijs-morgen/', { app: true, title: `Stroomprijs morgen (${nlDate(TOMORROW)}) – prijs per uur`, desc: 'De dynamische stroomprijs van morgen per uur, zodra de day-ahead veiling bekend is (meestal rond 13:00–15:00 uur). Met de goedkoopste uren en een planner.', modified: LIVE_UPDATED, schema: graph(crumbs(['Stroomprijs morgen', '/stroomprijs-morgen/']), dayDataset('/stroomprijs-morgen/', TOMORROW)), body: `<header class="pg-h"><h1>Stroomprijs morgen</h1><p>${nlDate(TOMORROW)}</p></header>${modebar()}${daySec('tomorrow', 'Prijs per uur')}${planner('tomorrow')}<div class="prose"><p>Morgen plannen? Abonneer je op de <a href="${BASE}/goedkoopste-uren.ics">agenda met de goedkoopste uren</a> of de <a href="${BASE}/feed.xml">RSS-feed</a>. De prijzen van morgen worden bekend na de day-ahead veiling (rond 12:00 uur); deze site ververst elk uur.</p></div>${placeholder}${updated}` });

// ---------- gas ----------
const gasDays = [...new Set(GASD.map(x => R.gasDay(x.t)))].filter(d => d >= R.gasDay(+now)).map(d => { const hs = GASD.filter(x => R.gasDay(x.t) === d); return { d, p: hs.reduce((s, x) => s + x.p, 0) / hs.length }; });
const gRate = yearRate.g;
page('/gasprijs-vandaag/', { app: true, title: `Gasprijs vandaag (${nlDate(TODAY)}) – prijs per m³`, desc: 'De dynamische gasprijs van vandaag per m³, gebaseerd op de day-ahead gasmarkt (TTF), via EnergyZero. Met een schatting incl. energiebelasting en btw.', modified: LIVE_UPDATED, schema: graph(crumbs(['Gasprijs vandaag', '/gasprijs-vandaag/'])), body: `<header class="pg-h"><h1>Gasprijs vandaag</h1><p>${nlDate(TODAY)}</p></header>${modebar(true)}<section class="sec" aria-labelledby="gas-h"><h2 id="gas-h" class="sr">Gasprijs nu</h2><div data-c="gas">${R.gas(C)}</div>
${gasDays.length ? `<div class="tbl tbl-w"><table class="rates"><caption>Gasprijs per m³ per gasdag (06:00 tot 06:00 uur)</caption><thead><tr><th scope="col">Gasdag</th><th scope="col">Excl. btw</th><th scope="col">Incl. btw</th><th scope="col">All-in*</th></tr></thead><tbody>${gasDays.map(g => `<tr><th scope="row">${nlDate(g.d, { weekday: 'short', day: 'numeric', month: 'short' })}</th><td>${eur(g.p)}</td><td>${eur(g.p * TAX.vat)}</td><td>${eur((g.p + gRate) * TAX.vat)}</td></tr>`).join('')}</tbody></table></div><p class="note">* Marktprijs + energiebelasting ${rateYear} (${eur(gRate, 5)} per m³) + 21% btw, zonder opslag van je leverancier en zonder vaste kosten. <a href="${BASE}/zo-rekenen-we/">Zo rekenen we</a>.</p>` : ''}</section>
<div class="prose"><h2>Hoe werkt een dynamische gasprijs?</h2><p>Bij een dynamisch gascontract betaal je de marktprijs voor aardgas plus een vaste opslag van je leverancier, energiebelasting en btw. De marktprijs volgt de Nederlandse groothandelsmarkt TTF en verandert per dag (niet per uur zoals stroom); leveranciers gebruiken een gasdag van 06:00 tot 06:00 uur. Wil je minder gas gebruiken? Check of je <a href="https://cerberostech.github.io/isde-checker/">ISDE-subsidie op een warmtepomp</a> kunt krijgen.</p></div>${placeholder}${updated}` });

// ---------- zo rekenen we ----------
const red = TAX.reduction[rateYear];
page('/zo-rekenen-we/', { title: 'Zo rekenen we – schatting van je stroomprijs incl. belasting', desc: `Hoe Stroomprijs de prijs incl. energiebelasting en btw schat: de formule, de tarieven voor ${rateYear} met bron, wat er niet in zit en hoe de prijsklassen A–G werken.`, modified: STATIC_UPDATED, schema: graph(crumbs(['Zo rekenen we', '/zo-rekenen-we/'])), body: `<header class="pg-h"><h1>Zo rekenen we</h1><p>Wat de getallen op deze site betekenen, en wat ze niet zijn.</p></header><div class="prose">
<h2>Kale marktprijs</h2><p>Standaard zie je de <b>kale marktprijs</b>: de uitkomst van de day-ahead veiling van EPEX Spot voor Nederland, opgehaald via de publieke API van EnergyZero. Die prijs is <b>exclusief btw</b>, energiebelasting en de opslag van je leverancier. Dit is de enige prijs die we echt meten.</p>
<h2>Schatting all-in</h2><p>Kies je ‘Schatting all-in’, dan rekenen we per uur:</p><p class="formula">(marktprijs + opslag leverancier + energiebelasting) × 1,21</p><p>De 1,21 is 21% btw. De opslag is standaard 0; vul de inkoopvergoeding van je eigen contract in voor een betere schatting. Je instelling blijft alleen in je eigen browser bewaard.</p>
<table class="rates"><caption>Energiebelasting ${rateYear}, eerste schijf, excl. btw</caption><thead><tr><th scope="col">Soort</th><th scope="col">Tarief</th><th scope="col">Incl. 21% btw</th></tr></thead><tbody><tr><th scope="row">Elektriciteit (0–10.000 kWh)</th><td>€&nbsp;${nf(yearRate.e, 5)} per kWh</td><td>€&nbsp;${nf(yearRate.e * TAX.vat, 5)}</td></tr><tr><th scope="row">Aardgas (0–170.000 m³)</th><td>€&nbsp;${nf(yearRate.g, 5)} per m³</td><td>€&nbsp;${nf(yearRate.g * TAX.vat, 5)}</td></tr></tbody></table>
<p>Bron: <a href="${TAX.source}">Belastingdienst, energiebelasting</a> (gecontroleerd op ${shortDate(TAX.checked)}).${TAX.rates[TODAY.slice(0, 4)] ? '' : ` Let op: de tarieven voor ${TODAY.slice(0, 4)} zijn nog niet verwerkt; we gebruiken die van ${TAX.fallback}.`}</p>
<h2>Wat er niet in zit</h2><ul><li>Vaste leveringskosten van je leverancier.</li><li>Netbeheerkosten (vast bedrag per maand).</li><li>De vermindering energiebelasting: een vast bedrag per jaar per aansluiting${red ? ` (${rateYear}: €&nbsp;${nf(red, 2)} excl. btw)` : ''}. Die hangt niet af van het uur, dus we trekken hem niet af per kWh.</li><li>Kwartierprijzen: sommige leveranciers rekenen per kwartier. Wij tonen uurprijzen.</li></ul><p>De schatting is dus een benadering van wat één extra kWh je op dat uur kost. Je echte rekening staat bij je leverancier.</p>
<h2>Waarom het goedkoopste moment niet verandert</h2><p>Belasting en opslag zijn per kWh op elk uur van de dag gelijk. Daardoor blijft het goedkoopste uur in beide weergaven hetzelfde uur. Alleen de bedragen veranderen.</p>
<h2>Prijsklasse A tot G</h2><p>Per dag delen we het verschil tussen het goedkoopste en het duurste uur in zeven gelijke stappen. Een uur in klasse A hoort bij de goedkoopste stap van die dag, klasse G bij de duurste. De kleuren en letters lijken op het energielabel, maar ze zijn relatief per dag: klasse A is niet altijd goedkoop in euro’s. Liggen de prijzen op een dag dicht bij elkaar, dan zeggen we dat erbij.</p>
<h2>De planner</h2><p>De planner zoekt het aaneengesloten blok uren met de laagste gemiddelde prijs. Het verbruik per apparaat is een voorbeeldwaarde die je zelf aanpast. We rekenen alsof het apparaat gelijkmatig verbruikt; een wasmachine verbruikt in werkelijkheid het meest aan het begin (opwarmen).</p></div>` });

// ---------- dynamisch vs vast ----------
const row = (k, a, b) => `<tr><th scope="row">${k}</th><td data-l="Dynamisch">${a}</td><td data-l="Vast">${b}</td></tr>`;
page('/dynamisch-vs-vast-contract/', { title: 'Dynamisch vs vast energiecontract: de verschillen', desc: 'Feitelijke vergelijking van een dynamisch, variabel en vast energiecontract: hoe de prijs tot stand komt, risico’s en voor wie het past. Met bronnen.', modified: STATIC_UPDATED, schema: graph(crumbs(['Dynamisch vs vast contract', '/dynamisch-vs-vast-contract/'])), body: `<header class="pg-h"><h1>Dynamisch vs vast energiecontract</h1></header><section class="sec"><div class="tbl-w"><table class="cmp-t"><thead><tr><td></td><th scope="col">Dynamisch</th><th scope="col">Vast</th></tr></thead><tbody>${row('Prijs stroom', 'Verandert per uur (day-ahead marktprijs + opslag)', 'Vaste prijs per kWh voor de looptijd (1–5 jaar)')}${row('Prijs gas', 'Verandert per dag', 'Vast voor de looptijd')}${row('Risico', 'Je draagt het marktrisico: pieken én dalen', 'Leverancier draagt het risico; je betaalt daar een premie voor')}${row('Opzeggen', 'Meestal maandelijks opzegbaar', 'Opzegvergoeding mogelijk bij vroegtijdig opzeggen')}${row('Slimme meter', 'Nodig', 'Niet nodig')}${row('Voordeel als…', 'Je verbruik kunt verschuiven (EV, warmtepomp, thuisbatterij, wasmachine)', 'Je zekerheid wilt over je maandbedrag')}</tbody></table></div></section>
<div class="prose"><h2>Hoe komt de dynamische prijs tot stand?</h2><p>Elke dag rond 12:00 uur sluit de day-ahead veiling van EPEX Spot. Daarin wordt per tijdsblok de groothandelsprijs voor stroom in Nederland voor de volgende dag bepaald. De uitkomst is openbaar via het ENTSO-E Transparency Platform. Je leverancier rekent die prijs door, plus een opslag (inkoopvergoeding), energiebelasting, en 21% btw. Daarnaast betaal je vaste leveringskosten en netbeheerkosten. Op zonnige of winderige momenten kan de marktprijs zelfs negatief worden. <a href="${BASE}/zo-rekenen-we/">Zo schatten wij de prijs incl. belasting</a>.</p>
<h2>Wat zijn de risico’s?</h2><p>Als de groothandelsprijs stijgt, zoals in 2022, stijgt je rekening direct mee. Bij een vast contract ben je daartegen beschermd zolang het contract loopt. Een dynamisch contract loont vooral als je stroom gebruikt wanneer die goedkoop is.</p>
<h2>Terugleveren en de salderingsregeling</h2><p>De salderingsregeling voor zonnepanelen stopt per 1 januari 2027. Daarna krijg je voor teruggeleverde stroom een terugleververgoeding van je leverancier. Bij een dynamisch contract hangt die vergoeding vaak af van de uurprijs, dus op momenten met negatieve prijzen kan terugleveren geld kosten. Check de voorwaarden van je leverancier.</p>
<h2>Bronnen</h2><ul><li><a href="https://consument.acm.nl/elektriciteit-en-gas/wat-betaal-ik-voor-mijn-energie/vaste-variabele-leveringskosten-energie">ACM ConsuWijzer: vaste en variabele leveringskosten energie</a></li><li><a href="https://www.rijksoverheid.nl/onderwerpen/energie-thuis/salderingsregeling">Rijksoverheid: salderingsregeling</a></li><li><a href="${TAX.source}">Belastingdienst: energiebelasting</a></li><li><a href="https://transparency.entsoe.eu/">ENTSO-E Transparency Platform</a></li><li><a href="https://www.epexspot.com/en/market-results">EPEX Spot market results</a></li></ul></div>${placeholder}` });

