// gas
page('/en/gas-price-today/', { app: true, title: `Gas Price Netherlands Today (${enDate(TODAY, { day: 'numeric', month: 'long' })}) – per m³`, desc: 'Today’s dynamic gas price in the Netherlands per m³, based on the day-ahead gas market (TTF), via EnergyZero. With an estimate incl. energy tax and VAT.', modified: LIVE_UPDATED, schema: graph(crumbs(['Gas price today', '/en/gas-price-today/'])), body: `<header class="pg-h"><h1>Gas price today</h1><p>${enDate(TODAY)}</p></header>${modebar(true, true)}<section class="sec" aria-labelledby="gas-h"><h2 id="gas-h" class="sr">Gas price now</h2><div data-c="gas">${RE.gas(CE)}</div>
${gasDays.length ? `<div class="tbl tbl-w"><table class="rates"><caption>Gas price per m³ per gas day (06:00 to 06:00 ${tzNow})</caption><thead><tr><th scope="col">Gas day</th><th scope="col">Excl. VAT</th><th scope="col">Incl. VAT</th><th scope="col">All-in*</th></tr></thead><tbody>${gasDays.map(g => `<tr><th scope="row">${enDate(g.d, { weekday: 'short', day: 'numeric', month: 'short' })}</th><td>${eurEn(g.p)}</td><td>${eurEn(g.p * TAX.vat)}</td><td>${eurEn((g.p + gRate) * TAX.vat)}</td></tr>`).join('')}</tbody></table></div><p class="note">* Market price + energy tax ${rateYear} (${eurEn(gRate, 5)} per m³) + 21% VAT, without your supplier’s markup and without fixed charges. <a href="${BASE}/en/methodology/">How we calculate</a>.</p>` : ''}</section>
<div class="prose"><h2>How does a dynamic gas price work?</h2><p>On a dynamic gas contract you pay the market price for natural gas plus a fixed markup from your supplier, energy tax and VAT. The market price follows the Dutch wholesale market TTF and changes per day (not per hour, as electricity does); suppliers use a gas day from 06:00 to 06:00. Want to use less gas? Check whether you can get an <a href="https://cerberostech.github.io/isde-checker/" hreflang="nl">ISDE subsidy for a heat pump</a> (in Dutch).</p></div>${placeholderEn}${updatedEn}` });

// methodology
page('/en/methodology/', { title: 'How We Calculate: Electricity Price Estimate incl. Tax | Stroomprijs', desc: `How Stroomprijs estimates the price incl. energy tax and VAT: the formula, the ${rateYear} rates with source, what is not included and how price classes A–G work.`, modified: STATIC_UPDATED, schema: graph(crumbs(['How we calculate', '/en/methodology/'])), body: `<header class="pg-h"><h1>How we calculate</h1><p>What the numbers on this site mean, and what they are not.</p></header><div class="prose">
<h2>Market price</h2><p>By default you see the <b>market price</b>: the result of the EPEX Spot day-ahead auction for the Netherlands, fetched through the public EnergyZero API. This price is <b>excluding VAT</b>, energy tax and your supplier’s markup. It is the only price we actually measure. The English pages show it in euros per kWh (for example €0.1234 per kWh); the Dutch pages show the same price in cents.</p>
<h2>All-in estimate</h2><p>If you choose ‘All-in estimate’, we calculate for each hour:</p><p class="formula">(market price + supplier markup + energy tax) × 1.21</p><p>The 1.21 is 21% VAT. The markup is 0 by default; enter the purchasing fee from your own contract for a better estimate. Your setting is only stored in your own browser.</p>
<table class="rates"><caption>Energy tax ${rateYear}, first bracket, excl. VAT</caption><thead><tr><th scope="col">Type</th><th scope="col">Rate</th><th scope="col">Incl. 21% VAT</th></tr></thead><tbody><tr><th scope="row">Electricity (0–10,000 kWh)</th><td>${eurEn(yearRate.e, 5)} per kWh</td><td>${eurEn(yearRate.e * TAX.vat, 5)}</td></tr><tr><th scope="row">Natural gas (0–170,000 m³)</th><td>${eurEn(yearRate.g, 5)} per m³</td><td>${eurEn(yearRate.g * TAX.vat, 5)}</td></tr></tbody></table>
<p>Source: <a href="${TAX.source}" hreflang="nl">Belastingdienst (Dutch Tax Administration), energy tax</a> (in Dutch, checked on ${shortDate(TAX.checked, 'en-GB')}).${TAX.rates[TODAY.slice(0, 4)] ? '' : ` Note: the rates for ${TODAY.slice(0, 4)} have not been added yet; we use those for ${TAX.fallback}.`}</p>
<h2>What is not included</h2><ul><li>Your supplier’s fixed supply charges.</li><li>Network charges (a fixed amount per month).</li><li>The energy tax reduction: a fixed amount per year per connection${red ? ` (${rateYear}: ${eurEn(red, 2)} excl. VAT)` : ''}. It does not depend on the hour, so we do not deduct it per kWh.</li><li>Quarter-hour prices: some suppliers bill per quarter-hour. We show hourly prices.</li></ul><p>So the estimate is an approximation of what one extra kWh costs you in that hour. Your actual bill comes from your supplier.</p>
<h2>Why the cheapest time does not change</h2><p>Tax and markup are the same per kWh in every hour of the day. That is why the cheapest hour stays the same hour in both views. Only the amounts change.</p>
<h2>Price class A to G</h2><p>For each day we divide the range between the cheapest and the most expensive hour into seven equal steps. An hour in class A belongs to the cheapest step of that day, class G to the most expensive. The colours and letters look like the EU energy label, but they are relative to each day: class A is not always cheap in euros. If the prices on a day are close together, we say so.</p>
<h2>Times</h2><p>All times are Dutch local time (Europe/Amsterdam): CET (UTC+1) in winter and CEST (UTC+2) in summer.</p>
<h2>The planner</h2><p>The planner finds the continuous block of hours with the lowest average price. The usage per appliance is an example value that you can change. We calculate as if the appliance uses power evenly; in reality a washing machine uses the most at the start (heating up).</p></div>` });

// dynamic vs fixed
const rowEn = (k, a, b) => `<tr><th scope="row">${k}</th><td data-l="Dynamic">${a}</td><td data-l="Fixed">${b}</td></tr>`;
page('/en/dynamic-vs-fixed-contract/', { title: 'Dynamic vs Fixed Energy Contract: The Differences', desc: 'A factual comparison of a dynamic and a fixed energy contract in the Netherlands: how the price is set, the risks and who each one suits. With sources.', modified: STATIC_UPDATED, schema: graph(crumbs(['Dynamic vs fixed contract', '/en/dynamic-vs-fixed-contract/'])), body: `<header class="pg-h"><h1>Dynamic vs fixed energy contract</h1></header><section class="sec"><div class="tbl-w"><table class="cmp-t"><thead><tr><td></td><th scope="col">Dynamic</th><th scope="col">Fixed</th></tr></thead><tbody>${rowEn('Electricity price', 'Changes every hour (day-ahead market price + markup)', 'Fixed price per kWh for the contract term (1–5 years)')}${rowEn('Gas price', 'Changes every day', 'Fixed for the contract term')}${rowEn('Risk', 'You carry the market risk: peaks and dips', 'The supplier carries the risk; you pay a premium for that')}${rowEn('Cancelling', 'Usually cancellable every month', 'An early termination fee may apply')}${rowEn('Smart meter', 'Required', 'Not required')}${rowEn('Pays off if…', 'You can shift your usage (EV, heat pump, home battery, washing machine)', 'You want certainty about your monthly payment')}</tbody></table></div></section>
<div class="prose"><h2>How is the dynamic price set?</h2><p>Every day around 12:00 ${tzNow}, the EPEX Spot day-ahead auction closes. It sets the wholesale electricity price in the Netherlands for each time slot of the next day. The result is public on the ENTSO-E Transparency Platform. Your supplier passes this price on, plus a markup (purchasing fee), energy tax and 21% VAT. You also pay fixed supply charges and network charges. At sunny or windy moments the market price can even turn negative. <a href="${BASE}/en/methodology/">How we estimate the price incl. tax</a>.</p>
<h2>What are the risks?</h2><p>If the wholesale price rises, as in 2022, your bill rises straight away. A fixed contract protects you from this for as long as the contract runs. A dynamic contract pays off mainly if you use electricity when it is cheap.</p>
<h2>Feeding back and the net metering scheme</h2><p>The net metering scheme for solar panels (salderingsregeling) ends on 1 January 2027. After that, your supplier pays you a feed-in fee for the electricity you feed back to the grid. On a dynamic contract this fee often depends on the hourly price, so feeding back can cost money at times of negative prices. Check your supplier’s terms.</p>
<h2>Sources</h2><ul><li><a href="https://consument.acm.nl/elektriciteit-en-gas/wat-betaal-ik-voor-mijn-energie/vaste-variabele-leveringskosten-energie" hreflang="nl">ACM ConsuWijzer: fixed and variable energy supply costs</a> (in Dutch)</li><li><a href="https://www.rijksoverheid.nl/onderwerpen/energie-thuis/salderingsregeling" hreflang="nl">Government of the Netherlands: net metering scheme</a> (in Dutch)</li><li><a href="${TAX.source}" hreflang="nl">Belastingdienst: energy tax</a> (in Dutch)</li><li><a href="https://transparency.entsoe.eu/">ENTSO-E Transparency Platform</a></li><li><a href="https://www.epexspot.com/en/market-results">EPEX Spot market results</a></li></ul></div>${placeholderEn}` });

// FAQ
const faqEn = [
  ['Where do these prices come from?', 'From the EPEX Spot day-ahead auction for the Netherlands (also published on the ENTSO-E Transparency Platform). We fetch them every hour through the free, public EnergyZero API.'],
  ['Are these the prices I pay?', 'No. By default you see the market price excl. VAT. On top of that you pay your supplier’s markup, energy tax, 21% VAT, fixed supply charges and network charges. The pattern over the day (when it is cheap) is the same, though.'],
  ['What is the all-in estimate?', `With the ‘All-in estimate’ button we add the energy tax per kWh (${rateYear}: ${eurEn(yearRate.e, 5)} excl. VAT) and, if you enter it, your own supplier markup to the market price, and then add 21% VAT. Fixed charges and the energy tax reduction are not included. It is an approximation; the ‘How we calculate’ page explains it.`],
  ['What do the letters A to G mean?', 'For each day we divide the range between the cheapest and the most expensive hour into seven equal steps. A is the cheapest step of that day, G the most expensive. The letters are relative to each day, so they are not a fixed price threshold.'],
  ['What time are tomorrow’s prices published?', 'The day-ahead auction closes around 12:00 CET/CEST. The result is usually known around 13:00; this site refreshes every hour, so the prices appear here at most an hour later.'],
  ['Which time zone are the times in?', 'All times on this site are Dutch local time (Europe/Amsterdam): CET (UTC+1) in winter and CEST (UTC+2) in summer.'],
  ['Why is the electricity price sometimes negative?', 'When there is a lot of solar and wind power and little demand, there is more supply than needed. Producers then sometimes pay to get rid of their electricity. With a dynamic contract you can benefit from this, although you still pay energy tax on every kWh.'],
  ['When is the best time to run my washing machine?', 'Use the planner on the dashboard. Choose your appliance, adjust the duration and the usage, and you see the cheapest continuous block from now on, what it costs and how much you save. You can also add the block to your calendar.'],
  ['How do I use the calendar feed?', 'Add the .ics link as a subscribed calendar in Google Calendar, Outlook or Apple Calendar. You then automatically see the cheapest 3-hour block of today and tomorrow. The event titles are in Dutch.'],
  ['Does this site cost money or collect data?', 'No. The site is free, with no account and no cookies of our own. Your settings (view, markup, colour scheme) stay in your own browser only. See the privacy page.'],
];
page('/en/faq/', { title: 'Dynamic Energy Prices Netherlands: Frequently Asked Questions | Stroomprijs', desc: 'Answers to common questions about dynamic electricity and gas prices in the Netherlands: the estimate incl. tax, price classes, negative prices and when tomorrow’s prices are published.', modified: STATIC_UPDATED, schema: graph({ '@type': 'FAQPage', inLanguage: 'en', mainEntity: faqEn.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) }, crumbs(['Frequently asked questions', '/en/faq/'])), body: `<header class="pg-h"><h1>Frequently asked questions</h1></header><div class="faq">${faqEn.map(([q, a]) => `<section class="qa"><h2>${esc(q)}</h2><p>${esc(a)}</p></section>`).join('')}</div>` });

// privacy
page('/en/privacy/', { modified: STATIC_UPDATED, title: 'Privacy & Disclosure | Stroomprijs', desc: 'Privacy statement and disclosure: bol.com partner links, no account, open source.', body: `<header class="pg-h"><h1>Privacy &amp; disclosure</h1></header><div class="prose"><h2>Affiliate links from bol.com</h2><p>We are a <b>bol.com partner</b>. The block ‘Handy for measuring your electricity use’ contains links to search results on bol.com, for example for a P1 meter or a smart plug with an energy meter. If you buy something through such a link, bol.com pays us a small commission. You pay nothing extra.</p><p>These links only appear on the <a href="${BASE}/en/">dashboard</a> and below each <a href="${BASE}/en/guides/">guide</a>. They are marked as sponsored (<code>rel="sponsored"</code>) and carry the label ‘Affiliate links’. The commission has <b>no influence on the prices</b> we show: those come straight from the day-ahead market (see below).</p><p>We have no affiliate or partner agreements with energy suppliers or energy comparison sites. We earn nothing from your choice of energy contract. The site has a clearly marked empty space where a comparison widget (for example via Daisycon) may appear in the future. If that happens, we will update this page and mark those links as affiliate links.</p><h2>Privacy</h2><p>No account, no forms, no cookies of our own. The site is hosted on GitHub Pages; GitHub may log technical data such as your IP address (see the <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement</a>). We count visits anonymously with <a href="https://www.goatcounter.com/help/privacy">GoatCounter</a>: without cookies and without personal data. If you click a bol.com link, you go to the bol.com site, where the bol.com privacy and cookie policy applies.</p><p>We store your settings on this site (market price or estimate, your supplier markup, light or dark) with <code>localStorage</code> in your own browser. They are not sent anywhere. You can clear them in your browser settings.</p><h2>Data</h2><p>Prices: the EnergyZero public API, based on EPEX Spot day-ahead (ENTSO-E). We do our best, but we do not guarantee that the data is correct. Not financial advice. <a href="${BASE}/en/methodology/">How we calculate</a>.</p><p>Made by CerberosTech. Source code: <a href="https://github.com/CerberosTech/stroomprijs">GitHub</a>.</p></div>` });

// ---------- ICS + RSS ----------
const icsT = ms => new Date(ms).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const evs = [[TODAY, P.today], [TOMORROW, P.tomorrow]].filter(([, a]) => R.cheapest(a, 3)).map(([d, a]) => { const b = R.cheapest(a, 3);
  return ['BEGIN:VEVENT', `UID:goedkoopste-3u-${d}@cerberostech.github.io`, `DTSTAMP:${icsT(+now)}`, `DTSTART:${icsT(b.start)}`, `DTEND:${icsT(b.end)}`, `SUMMARY:⚡ Goedkoopste stroom ${hh(b.start)}-${hh(b.end)} (gem. ${ct(b.avg).replace(',', '.')}/kWh)`, `DESCRIPTION:Goedkoopste blok van 3 uur op ${d} (kale day-ahead prijs excl. btw). Bron: EnergyZero/EPEX. ${SITE}/`, `URL:${SITE}/`, 'TRANSP:TRANSPARENT', 'END:VEVENT'].join('\r\n'); });
fs.writeFileSync(path.join(OUT, 'goedkoopste-uren.ics'), ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//CerberosTech//Stroomprijs//NL', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'X-WR-CALNAME:Goedkoopste stroom-uren', 'X-WR-TIMEZONE:Europe/Amsterdam', 'REFRESH-INTERVAL;VALUE=DURATION:PT1H', ...evs, 'END:VCALENDAR'].join('\r\n') + '\r\n');
const rssItems = [[TOMORROW, P.tomorrow], [TODAY, P.today]].filter(([, a]) => R.cheapest(a, 3)).map(([d, a]) => { const b = R.cheapest(a, 3), mn = a.reduce((m, x) => (x.p < m.p ? x : m)), sorted = [...a].sort((x, y) => x.p - y.p).slice(0, 5);
  return `<item><title>${esc(`Goedkoopste stroom ${nlDate(d)}: ${hh(b.start)}–${hh(b.end)}`)}</title><link>${SITE}/${d === TODAY ? 'stroomprijs-vandaag' : 'stroomprijs-morgen'}/</link><guid isPermaLink="false">stroomprijs-${d}</guid><pubDate>${now.toUTCString()}</pubDate><description>${esc(`Goedkoopste blok van 3 uur: ${hh(b.start)}–${hh(b.end)}, gemiddeld ${ct(b.avg)}/kWh. Goedkoopste uur: ${hh(mn.t)} (${ct(mn.p)}). Top 5 goedkoopste uren: ${sorted.map(x => `${hh(x.t)} (${ct(x.p)})`).join(', ')}. Kale day-ahead prijzen excl. btw, bron EnergyZero/EPEX.`)}</description></item>`; }).join('');
fs.writeFileSync(path.join(OUT, 'feed.xml'), `<?xml version="1.0" encoding="UTF-8"?><rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom"><channel><title>Goedkoopste stroom-uren</title><link>${SITE}/</link><atom:link href="${SITE}/feed.xml" rel="self" type="application/rss+xml"/><description>Dagelijks de goedkoopste uren voor stroom in Nederland (day-ahead).</description><language>nl-nl</language><image><url>${SITE}/icon-192.png</url><title>Goedkoopste stroom-uren</title><link>${SITE}/</link></image><lastBuildDate>${now.toUTCString()}</lastBuildDate>${rssItems}</channel></rss>`);

// ---------- about (/over/, /en/about/) ----------
// The text is markdown in content/about/ (over.md = Dutch, about.md = English), rendered as-is. Dates: STATIC_UPDATED.
for (const [p, f, en] of [['/over/', 'over.md', false], ['/en/about/', 'about.md', true]]) {
  const { meta, body } = frontMatter(fs.readFileSync(path.join('content/about', f), 'utf8')), title = meta.title.trim(), desc = meta.description.trim();
  page(p, { modified: STATIC_UPDATED, title: en ? 'About Stroomprijs: Sources and Method' : title, desc, schema: graph({ '@type': 'AboutPage', '@id': SITE + p + '#page', url: SITE + p, name: title, description: desc, inLanguage: en ? 'en' : 'nl-NL', isPartOf: { '@id': SITE + (en ? '/en/' : '/') + '#site' }, about: { '@id': ORG['@id'] } }, ORG, crumbs([en ? 'About' : 'Over Stroomprijs', p])), body: `<header class="pg-h"><h1>${esc(title)}</h1><p>${esc(desc)}</p></header><div class="prose">${markdown(body, { base: BASE, guides: en ? '/en/guides' : '/gidsen' })}</div>` });
}

// ---------- data, sitemap, robots ----------
const iso = a => a.map(({ t, p }) => ({ t: new Date(t).toISOString().replace('.000Z', 'Z'), p }));
const gasDayOf = d => GASD.filter(x => R.at(x.t).day === d);
fs.writeFileSync(path.join(OUT, 'prices.json'), JSON.stringify({ fetched: data.fetched, source: data.source, status: data.status, unit: 'EUR/kWh (power), EUR/m3 (gas), excl. VAT', today: TODAY, tomorrow: TOMORROW, power: { today: iso(P.today), tomorrow: iso(P.tomorrow) }, gas: { today: iso(gasDayOf(TODAY)), tomorrow: iso(gasDayOf(TOMORROW)) } }, null, 1));
// <lastmod> is the page's own modified date (see page()); a guide without a date gets none, rather than a false "changed today".
const urls = ['/', '/stroomprijs-vandaag/', '/stroomprijs-morgen/', '/gasprijs-vandaag/', '/dynamisch-vs-vast-contract/', '/veelgestelde-vragen/', '/privacy/', '/gidsen/', '/zo-rekenen-we/', '/over/', ...guides.map(g => `/gidsen/${g.slug}/`), ...PAIRS.map(([, u]) => u), ...guidesEn.map(g => `/en/guides/${g.slug}/`)].map(u => [u, LASTMOD[u]]);
// Each paired URL lists both languages and x-default (Dutch) as xhtml:link alternates, itself included.
const alts = u => (ALT[u] ? [['nl', ALT[u].nl], ['en', ALT[u].en], ['x-default', ALT[u].nl]].map(([l, h]) => `<xhtml:link rel="alternate" hreflang="${l}" href="${SITE}${h}"/>`).join('') : '');
fs.writeFileSync(path.join(OUT, 'sitemap.xml'), `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${urls.map(([u, d]) => `<url><loc>${SITE}${u}</loc>${d ? `<lastmod>${d}</lastmod>` : ''}${alts(u)}</url>`).join('\n')}\n</urlset>\n`);
fs.writeFileSync(path.join(OUT, 'robots.txt'), `User-agent: *\nAllow: /\nSitemap: ${SITE}/sitemap.xml\n`);
fs.writeFileSync(path.join(OUT, '.nojekyll'), '');
console.log('built', fs.readdirSync(OUT).length, 'entries');
